// Arma la petición para el OCR local. Formato de la API de Mistral OCR (/v1/ocr): ajústalo si tu servidor espera otro.
const MODELO_OCR = 'mistral-ocr-latest';   // nombre del modelo en tu servidor de OCR
const d = $input.first().json;
if (!d.archivo || !d.archivo.base64) throw new Error('El portal no envió el archivo del CV');
const ext = String(d.archivo.extension || '').toLowerCase();
const MIME = { '.pdf': 'application/pdf', '.doc': 'application/msword', '.docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  '.jpg': 'image/jpeg', '.jpeg': 'image/jpeg', '.png': 'image/png', '.txt': 'text/plain' };
const mime = MIME[ext] || d.archivo.mime || 'application/octet-stream';
const url = 'data:' + mime + ';base64,' + d.archivo.base64;
const document = mime.startsWith('image/') ? { type: 'image_url', image_url: url } : { type: 'document_url', document_url: url, document_name: d.archivo.nombre };
return [{ json: { cv_id: d.cv_id, extension: ext, peticion: { model: MODELO_OCR, document, include_image_base64: false } } }];

// Une el texto de todas las páginas y anota alertas de lectura (páginas sin texto, documento casi vacío).
// Acepta la respuesta de Mistral OCR ({ pages: [{ index, markdown }] }) y otras comunes ({ text } / { markdown } / { content }).
const r = $input.first().json, alertas = [];
let paginas = Array.isArray(r.pages) ? r.pages.map((p, i) => ({ n: (p.index ?? i) + 1, t: String(p.markdown || p.text || '') })) : null;
let texto = paginas ? paginas.map(p => p.t).join('\n\n') : String(r.text || r.markdown || r.content || (r.data && r.data.text) || '');
// Quita imágenes incrustadas del markdown (![img-0.jpeg](img-0.jpeg)): no aportan texto
texto = texto.replace(/!\[[^\]]*\]\([^)]*\)/g, '').replace(/\u0000/g, '').trim();
if (paginas) paginas.forEach(p => { if (p.t.replace(/!\[[^\]]*\]\([^)]*\)/g, '').replace(/\s+/g, '').length < 40) alertas.push(`OCR: la página ${p.n} no tiene texto legible`); });
if (texto.replace(/\s+/g, '').length < 200) alertas.push('OCR: se leyó muy poco texto; el CV puede ser una imagen de baja calidad');
return [{ json: { texto, alertas_ocr: alertas } }];

// Texto del CV: el que leyó el portal (Word, texto) o el del OCR. Los datos de contacto suelen estar al inicio.
const d = $('Leer CV del portal').first().json;
const ocr = $input.first().json;
const texto = String(d.texto && d.texto.replace(/\s+/g, '').length > 200 ? d.texto : (ocr.texto || d.texto || '')).replace(/\u0000/g, '');
if (texto.replace(/\s+/g, '').length < 20) throw new Error('No se pudo leer texto del CV (ni el portal ni el OCR)');
const pedir = Object.entries(d.pedir).map(([k, v]) => `- ${k}: ${v}`).join('\n');
const prompt = `Lee el CV y devuelve SOLO este JSON:
{"nombre": "", "cedula": "", "email": "", "telefono": "", "alertas": ["..."]}

Datos a extraer:
${pedir}

Reglas:
${d.reglas.map(r => '- ' + r).join('\n')}
- En «alertas» anota, en español y en una línea cada una, lo que no encontraste o no pudiste leer bien (por ejemplo: «No aparece la cédula», «El teléfono está incompleto»).

<cv>
${texto.slice(0, 12000)}
</cv>`;
return [{ json: { prompt, texto: d.texto ? null : texto.slice(0, 60000), alertas_ocr: ocr.alertas_ocr || [] } }];

// Valida la respuesta del modelo (el portal vuelve a validar: solo llena datos vacíos y cruza la cédula).
const MODELO = 'Modelo local de n8n';   // escribe aquí el nombre de tus modelos (OCR + extracción): queda guardado con la lectura
const p = $('Preparar extracción').first().json;
let raw = String($input.first().json.text || '').trim().replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '');
const a = raw.indexOf('{'), b = raw.lastIndexOf('}');
if (a < 0 || b < a) throw new Error('El modelo no devolvió JSON');
let r; try { r = JSON.parse(raw.slice(a, b + 1)); } catch (e) { throw new Error('El modelo devolvió un JSON inválido: ' + e.message); }
const s = (v, n) => String(v == null ? '' : v).trim().slice(0, n);
const datos = { nombre: s(r.nombre, 120), cedula: s(r.cedula, 30), email: s(r.email, 160), telefono: s(r.telefono, 40) };
const alertas = [...(p.alertas_ocr || []), ...(Array.isArray(r.alertas) ? r.alertas : []).map(x => s(x, 300))].filter(Boolean).slice(0, 10);
return [{ json: { datos, alertas, modelo: MODELO, ...(p.texto ? { texto: p.texto } : {}) } }];
